@keyframes scraps-markdown-decode-accent {
  0% {
    content: "#";
  }
  14% {
    content: "7";
  }
  28% {
    content: "5";
  }
  42% {
    content: "5";
  }
  56% {
    content: "3";
  }
  70% {
    content: "F";
  }
  84% {
    content: "F";
  }
}

@keyframes scraps-markdown-decode-success {
  0% {
    content: "#";
  }
  14% {
    content: "0";
  }
  28% {
    content: "0";
  }
  42% {
    content: "F";
  }
  56% {
    content: "2";
  }
  70% {
    content: "6";
  }
  84% {
    content: "1";
  }
}

@keyframes scraps-markdown-decode-promotion {
  0% {
    content: "#";
  }
  14% {
    content: "F";
  }
  28% {
    content: "C";
  }
  42% {
    content: "5";
  }
  56% {
    content: "C";
  }
  70% {
    content: "B";
  }
  84% {
    content: "4";
  }
}

[data-scraps-decode] {
  position: relative;
  color: transparent;
  contain: style paint;
  opacity: 0;
  transition: opacity 200ms ease-out;
}

[data-scraps-decode].scraps-markdown-decode-visible {
  opacity: var(--scraps-markdown-decode-opacity, 1);
}

[data-streaming-hidden] {
  opacity: 0;
}

[data-scraps-decode]::after {
  content: "1";
  position: absolute;
  left: 50%;
  color: var(--scraps-markdown-glyph-color, CanvasText);
  font: inherit;
  pointer-events: none;
  transform: translateX(-50%);
  animation: var(--scraps-markdown-decode-animation) 160ms steps(1) infinite;
  animation-delay: var(--scraps-markdown-decode-delay, 0ms);
}

import { Fragment, type ReactNode } from "react";

import { Checkbox } from "./checkbox";
import { CodeBlock, InlineCode } from "./code";
import { Heading } from "./heading";
import { Container, Flex, Stack } from "./layout";
import { ExternalLink, Link } from "./link";
import { isInternalHref, isSafeHref } from "./markdown-parser";
import { Quote } from "./quote";
import { Separator } from "./separator";
import { Text } from "./text";

export function DefaultParagraph({ children }: { children: ReactNode }) {
  return (
    <Text as="p" size="md" density="comfortable">
      {children}
    </Text>
  );
}

const DEFAULT_HEADING_SIZE = ["2xl", "xl", "lg", "md", "sm", "xs"] as const;

export function DefaultHeading({
  children,
  level,
}: {
  children: ReactNode;
  level: 1 | 2 | 3 | 4 | 5 | 6;
}) {
  return (
    <Heading as={`h${level}`} size={DEFAULT_HEADING_SIZE[level - 1] ?? "lg"}>
      {children}
    </Heading>
  );
}

export function DefaultBlockquote({ children }: { children: ReactNode }) {
  return <Quote>{children}</Quote>;
}

export function DefaultInlineCode({ children }: { children: string }) {
  return <InlineCode variant="neutral">{children}</InlineCode>;
}

export function DefaultLink({
  children,
  href,
  title,
}: {
  children: ReactNode;
  href: string;
  title?: string | null;
}) {
  if (isInternalHref(href)) {
    return (
      <Link to={href} title={title ?? undefined}>
        {children}
      </Link>
    );
  }
  if (!isSafeHref(href)) return <span>{children}</span>;
  return (
    <ExternalLink href={href} title={title ?? undefined}>
      {children}
    </ExternalLink>
  );
}

export function DefaultCodeBlock({ children, lang }: { children: string; lang?: string }) {
  return <CodeBlock language={lang}>{children}</CodeBlock>;
}

export function DefaultHtmlBlock({ html }: { html: string }) {
  return <span dangerouslySetInnerHTML={{ __html: html }} />;
}

export function DefaultStrong({ children }: { children: ReactNode }) {
  return <strong>{children}</strong>;
}

export function DefaultEmphasis({ children }: { children: ReactNode }) {
  return <em>{children}</em>;
}

export function DefaultStrikethrough({ children }: { children: ReactNode }) {
  return <Text strikethrough>{children}</Text>;
}

export function DefaultUnorderedList({ children }: { children: ReactNode }) {
  return (
    <Stack as="ul" gap="sm" margin="0" role="list" className="list-disc">
      {children}
    </Stack>
  );
}

export function DefaultOrderedList({ children }: { children: ReactNode }) {
  return (
    <Stack as="ol" gap="sm" margin="0" role="list" className="list-decimal">
      {children}
    </Stack>
  );
}

export function DefaultListItem({ children }: { children: ReactNode; checked?: boolean }) {
  return <Container as="li">{children}</Container>;
}

export function DefaultTaskList({ children }: { children: ReactNode }) {
  return (
    <Stack as="ul" gap="sm" margin="0" padding="0" role="list" className="list-none">
      {children}
    </Stack>
  );
}

export function DefaultTaskListItem({
  checked,
  children,
}: {
  checked: boolean;
  children: ReactNode;
}) {
  return (
    <Flex as="li" gap="sm" align="center" className={checked ? "line-through" : undefined}>
      {children}
    </Flex>
  );
}

export function DefaultHorizontalRule() {
  return <Separator orientation="horizontal" />;
}

export function DefaultText({ children }: { children: string }) {
  return <Fragment>{children}</Fragment>;
}

export function DefaultLineBreak() {
  return <br />;
}

export function DefaultTable({ children }: { children: ReactNode }) {
  return (
    <Container border="primary" radius="md" overflowX="auto">
      <table className="w-full min-w-full border-collapse">{children}</table>
    </Container>
  );
}

export function DefaultTableHead({ children }: { children: ReactNode }) {
  return (
    <thead className="border-b-4 border-[var(--scraps-theme-border-primary)] bg-[var(--scraps-theme-surface300)] whitespace-nowrap">
      {children}
    </thead>
  );
}

export function DefaultTableBody({ children }: { children: ReactNode }) {
  return <tbody className="rounded-b-[6px] bg-background">{children}</tbody>;
}

export function DefaultTableRow({ children }: { children: ReactNode }) {
  return (
    <tr className="border-b border-[var(--scraps-theme-border-secondary)] align-baseline last:rounded-b-[6px] last:border-b-0">
      {children}
    </tr>
  );
}

type Align = "left" | "center" | "right";

const alignClasses: Record<Align, string> = {
  left: "text-left",
  center: "text-center",
  right: "text-right",
};

export function DefaultTableHeaderCell({
  align = "left",
  children,
}: {
  align?: Align;
  children: ReactNode;
}) {
  return (
    <th
      className={`px-4 py-1.5 first:rounded-tl-[6px] last:rounded-tr-[6px] ${alignClasses[align]}`}
    >
      {children}
    </th>
  );
}

export function DefaultTableCell({
  align = "left",
  children,
}: {
  align?: Align;
  children: ReactNode;
}) {
  return <td className={`px-4 py-3 ${alignClasses[align]}`}>{children}</td>;
}

export function DefaultTag() {
  return null;
}

export { Checkbox };

import DOMPurify from "isomorphic-dompurify";
import {
  Lexer as MarkedLexer,
  marked,
  type MarkedToken,
  type Token,
  type TokenizerExtension,
  type Tokens,
} from "marked";

export interface TagToken {
  attrs: Record<string, string>;
  data: unknown;
  level: "block" | "inline";
  name: string;
  raw: string;
  type: "tag";
}

export type MarkdownToken = MarkedToken | TagToken;

const TAG_START_RE = /\{%\s+[\w-]/;
const SELF_CLOSING_RE = /^\{%\s+([\w-]+)((?:\s+[\w-]+="[^"]*")*)\s+\/%\}/;
const BLOCK_RE = /^\{%\s+([\w-]+)((?:\s+[\w-]+="[^"]*")*)\s+%\}([\s\S]*?)\{%\s+\/\1\s+%\}/;
const ATTR_RE = /([\w-]+)="([^"]*)"/g;

function parseAttrs(raw: string): Record<string, string> {
  const attrs: Record<string, string> = {};
  for (const match of raw.matchAll(ATTR_RE)) {
    const [, key, value] = match;
    if (key !== undefined && value !== undefined) attrs[key] = value;
  }
  return attrs;
}

function parseBody(body: string): unknown {
  if (!body) return undefined;
  try {
    return JSON.parse(body);
  } catch {
    return undefined;
  }
}

function findTagStart(source: string): number | undefined {
  let offset = 0;
  while (offset < source.length) {
    const index = source.slice(offset).search(TAG_START_RE);
    if (index === -1) return undefined;
    const absoluteIndex = offset + index;
    const rest = source.slice(absoluteIndex);
    if (BLOCK_RE.test(rest) || SELF_CLOSING_RE.test(rest)) return absoluteIndex;
    offset = absoluteIndex + 2;
  }
  return undefined;
}

function tokenizeTag(source: string, level: TagToken["level"]): Tokens.Generic | undefined {
  let match = BLOCK_RE.exec(source);
  if (match) {
    const [raw, name, attrSource = "", body = ""] = match;
    if (!name) return undefined;
    return {
      type: "tag",
      raw,
      level,
      name,
      attrs: parseAttrs(attrSource),
      data: parseBody(body),
    };
  }
  match = SELF_CLOSING_RE.exec(source);
  if (!match) return undefined;
  const [raw, name, attrSource = ""] = match;
  if (!name) return undefined;
  return {
    type: "tag",
    raw,
    level,
    name,
    attrs: parseAttrs(attrSource),
    data: undefined,
  };
}

const blockTagExtension: TokenizerExtension = {
  name: "tag",
  level: "block",
  start(source) {
    const index = findTagStart(source);
    if (index === undefined) return undefined;
    const lineStart = source.lastIndexOf("\n", index) + 1;
    return /\S/.test(source.slice(lineStart, index)) ? undefined : index;
  },
  tokenizer(source) {
    return tokenizeTag(source, "block");
  },
};

const inlineTagExtension: TokenizerExtension = {
  name: "tag",
  level: "inline",
  start: findTagStart,
  tokenizer(source) {
    return tokenizeTag(source, "inline");
  },
};

marked.use({ extensions: [blockTagExtension, inlineTagExtension] });

const SAFE_LINK_PATTERN = /^(https?:|mailto:)/i;
const INTERNAL_PATH_PATTERN = /^\/[^/]/;

export function isSafeHref(href: string): boolean {
  try {
    return SAFE_LINK_PATTERN.test(decodeURIComponent(unescape(href)));
  } catch {
    return false;
  }
}

export function isInternalHref(href: string): boolean {
  try {
    return INTERNAL_PATH_PATTERN.test(decodeURIComponent(unescape(href)));
  } catch {
    return false;
  }
}

const ALLOWED_TAGS = [
  "p",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "blockquote",
  "pre",
  "ul",
  "ol",
  "li",
  "hr",
  "br",
  "table",
  "thead",
  "tbody",
  "tr",
  "th",
  "td",
  "a",
  "code",
  "em",
  "strong",
  "del",
  "span",
  "b",
  "i",
  "sub",
  "sup",
];

const ALLOWED_ATTR = ["href", "title", "alt", "class", "id", "align"];

export function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, { ALLOWED_TAGS, ALLOWED_ATTR });
}

export function lexMarkdown(raw: string): MarkdownToken[] {
  return MarkedLexer.lex(raw) as MarkdownToken[];
}

export function isTagToken(token: Token | TagToken): token is TagToken {
  return token.type === "tag" && "attrs" in token && "level" in token;
}

"use client";

import { useReducedMotion } from "framer-motion";
import { useEffect, useLayoutEffect, useRef, type RefObject } from "react";

import "./markdown.css";

const STAGGER_MS = 8;
const FADE_LEAD_MS = 120;
const MAX_DURATION_MS = 1_280;
const CYCLE_DURATION_MS = 160;
const DECODE_ATTRIBUTE = "data-scraps-decode";
const segmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });
const dummyWrapper = typeof document === "undefined" ? null : document.createElement("span");

export function countMarkdownGraphemes(value: string): number {
  return [...segmenter.segment(value)].length;
}

type Animation = {
  destroy: () => void;
  settle: () => void;
};

const noopAnimation: Animation = { destroy() {}, settle() {} };

type TextRun = {
  active: boolean[];
  collapseCursor: number;
  decoratedAncestors: Element[];
  globalOffset: number;
  graphemes: string[];
  original: string;
  revealed: boolean;
  spans: HTMLSpanElement[];
  wrapper: HTMLSpanElement;
};

export function useStreamingAnimation(
  containerRef: RefObject<HTMLElement | null>,
  enabled: boolean,
): void {
  const prefersReducedMotion = useReducedMotion();

  useEffect(() => {
    const container = containerRef.current;
    if (!enabled || !container || prefersReducedMotion) return;

    let activeAnimations: Animation[] = [];
    const observer = new MutationObserver((mutations) => {
      activeAnimations.forEach((animation) => animation.settle());
      activeAnimations = [];
      const newElements: HTMLElement[] = [];
      for (const mutation of mutations) {
        for (const addedNode of mutation.addedNodes) {
          if (addedNode instanceof HTMLElement) newElements.push(addedNode);
        }
      }

      let characterOffset = 0;
      for (const element of newElements) {
        const skippedCharacters = Number.parseInt(element.dataset.skip ?? "0", 10);
        const totalCharacters = countMarkdownGraphemes(element.textContent ?? "");
        activeAnimations.push(animateElement(element, characterOffset));
        characterOffset += Math.max(0, totalCharacters - skippedCharacters);
      }
    });

    observer.observe(container, { childList: true });
    return () => {
      observer.disconnect();
      activeAnimations.forEach((animation) => animation.destroy());
      activeAnimations = [];
    };
  }, [containerRef, enabled, prefersReducedMotion]);
}

export function useTextDecodeAnimation(ref: RefObject<HTMLElement | null>, key: unknown): void {
  const prefersReducedMotion = useReducedMotion();
  const isInitial = useRef(true);

  useLayoutEffect(() => {
    if (isInitial.current) {
      isInitial.current = false;
      return;
    }
    if (prefersReducedMotion || !ref.current) return;
    const animation = animateElement(ref.current);
    return () => animation.destroy();
  }, [key, prefersReducedMotion, ref]);
}

function isSimpleCharacter(grapheme: string): boolean {
  return grapheme.length === 1 && !/\s/.test(grapheme);
}

const decodeAnimations = [
  "scraps-markdown-decode-accent",
  "scraps-markdown-decode-success",
  "scraps-markdown-decode-promotion",
] as const;

export const streamingAnimationStyles = `
@keyframes scraps-markdown-decode-accent { 0% { content: "#"; } 14% { content: "7"; } 28% { content: "5"; } 42% { content: "5"; } 56% { content: "3"; } 70% { content: "F"; } 84% { content: "F"; } }
@keyframes scraps-markdown-decode-success { 0% { content: "#"; } 14% { content: "0"; } 28% { content: "0"; } 42% { content: "F"; } 56% { content: "2"; } 70% { content: "6"; } 84% { content: "1"; } }
@keyframes scraps-markdown-decode-promotion { 0% { content: "#"; } 14% { content: "F"; } 28% { content: "C"; } 42% { content: "5"; } 56% { content: "C"; } 70% { content: "B"; } 84% { content: "4"; } }
[data-scraps-decode] { position: relative; color: transparent; contain: style paint; opacity: 0; transition: opacity 200ms ease-out; }
[data-scraps-decode].scraps-markdown-decode-visible { opacity: var(--scraps-markdown-decode-opacity, 1); }
[data-streaming-hidden] { opacity: 0; }
[data-scraps-decode]::after { content: "1"; position: absolute; left: 50%; color: var(--scraps-markdown-glyph-color, CanvasText); font: inherit; pointer-events: none; transform: translateX(-50%); animation: var(--scraps-markdown-decode-animation) 160ms steps(1) infinite; animation-delay: var(--scraps-markdown-decode-delay, 0ms); }
`;

function prepareTextNode(
  textNode: Text,
  globalOffset: number,
  skipCharacters: number,
  root: Element,
): TextRun | null {
  const original = textNode.nodeValue ?? "";
  const parent = textNode.parentNode;
  if (!original.trim() || !parent || !dummyWrapper) return null;

  const decoratedAncestors: Element[] = [];
  let ancestor = parent instanceof Element ? parent : null;
  while (ancestor && ancestor !== root) {
    decoratedAncestors.push(ancestor);
    ancestor = ancestor.parentElement;
  }
  const graphemes = Array.from(segmenter.segment(original), ({ segment }) => segment);

  if (globalOffset + graphemes.length <= skipCharacters) {
    return {
      original,
      wrapper: dummyWrapper,
      spans: [],
      graphemes,
      active: [],
      globalOffset,
      collapseCursor: 0,
      decoratedAncestors,
      revealed: true,
    };
  }

  const wrapper = document.createElement("span");
  wrapper.style.setProperty(
    "--scraps-markdown-glyph-color",
    getComputedStyle(parent as Element).color,
  );
  const spans: HTMLSpanElement[] = [];
  const active: boolean[] = [];

  graphemes.forEach((grapheme, index) => {
    const span = document.createElement("span");
    span.textContent = grapheme;
    if (isSimpleCharacter(grapheme) && globalOffset + index >= skipCharacters) {
      span.setAttribute(DECODE_ATTRIBUTE, "");
      span.style.setProperty(
        "--scraps-markdown-decode-delay",
        `${-Math.random() * CYCLE_DURATION_MS}ms`,
      );
      span.style.setProperty(
        "--scraps-markdown-decode-animation",
        decodeAnimations[index % decodeAnimations.length] ?? decodeAnimations[0],
      );
      span.style.setProperty("--scraps-markdown-decode-opacity", String(0.4 + Math.random() * 0.6));
      active.push(true);
    } else {
      active.push(false);
    }
    spans.push(span);
    wrapper.append(span);
  });

  textNode.replaceWith(wrapper);
  return {
    original,
    wrapper,
    spans,
    graphemes,
    active,
    globalOffset,
    collapseCursor: 0,
    decoratedAncestors,
    revealed: !active.includes(true),
  };
}

function collapseSettledPrefix(run: TextRun) {
  let collapseEnd = run.collapseCursor;
  for (let index = run.collapseCursor; index < run.spans.length; index++) {
    if (run.active[index]) break;
    const grapheme = run.graphemes[index];
    if (grapheme && /\s/.test(grapheme)) collapseEnd = index + 1;
  }
  if (collapseEnd <= run.collapseCursor) return;

  const text = run.graphemes.slice(run.collapseCursor, collapseEnd).join("");
  const firstSpan = run.spans[run.collapseCursor];
  if (firstSpan) firstSpan.replaceWith(document.createTextNode(text));
  for (let index = run.collapseCursor + 1; index < collapseEnd; index++) {
    run.spans[index]?.remove();
  }
  run.collapseCursor = collapseEnd;
}

function restoreRuns(runs: TextRun[]) {
  for (const run of runs) {
    if (run.wrapper.isConnected) run.wrapper.replaceWith(document.createTextNode(run.original));
  }
}

function fadeOutRuns(runs: TextRun[]) {
  for (const run of runs) {
    for (let index = run.collapseCursor; index < run.spans.length; index++) {
      const span = run.spans[index];
      if (!span) continue;
      span.removeAttribute(DECODE_ATTRIBUTE);
      span.classList.add("scraps-markdown-decode-visible");
    }
  }
  return window.setTimeout(() => restoreRuns(runs), 200);
}

const scheduleIdle = (callback: () => void) =>
  typeof window.requestIdleCallback === "function"
    ? window.requestIdleCallback(callback)
    : window.setTimeout(callback, 0);

const cancelIdle = (id: number) => {
  if (typeof window.cancelIdleCallback === "function") window.cancelIdleCallback(id);
  else window.clearTimeout(id);
};

function animateElement(element: HTMLElement, characterOffset = 0): Animation {
  const skipCharacters = Number.parseInt(element.dataset.skip ?? "0", 10);
  delete element.dataset.skip;
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  const textNodes: Text[] = [];
  let node = walker.nextNode();
  while (node) {
    if (node.textContent?.trim()) textNodes.push(node as Text);
    node = walker.nextNode();
  }
  if (textNodes.length === 0) return noopAnimation;

  const runs: TextRun[] = [];
  let globalIndex = 0;
  for (const textNode of textNodes) {
    const run = prepareTextNode(textNode, globalIndex, skipCharacters, element);
    if (!run) continue;
    runs.push(run);
    globalIndex += run.graphemes.length;
  }
  if (runs.length === 0) return noopAnimation;

  const sharedAncestors = new Set<Element>();
  runs
    .filter((run) => run.revealed)
    .forEach((run) => {
      run.decoratedAncestors.forEach((ancestor) => sharedAncestors.add(ancestor));
    });
  runs
    .filter((run) => !run.revealed)
    .forEach((run) => {
      run.decoratedAncestors.forEach((ancestor) => {
        if (!sharedAncestors.has(ancestor)) ancestor.setAttribute("data-streaming-hidden", "");
      });
    });

  let settled = false;
  const startTime = performance.now();
  let pendingIdle: number | null = null;
  let fadeTimeout: number | null = null;

  function revealAll() {
    runs.forEach((run) => {
      run.decoratedAncestors.forEach((ancestor) =>
        ancestor.removeAttribute("data-streaming-hidden"),
      );
    });
  }

  function scheduleCollapse() {
    if (pendingIdle !== null) return;
    pendingIdle = scheduleIdle(() => {
      pendingIdle = null;
      if (!settled) runs.forEach(collapseSettledPrefix);
    });
  }

  function settle() {
    if (settled) return;
    settled = true;
    revealAll();
    if (pendingIdle !== null) cancelIdle(pendingIdle);
    pendingIdle = null;
    runs.forEach(collapseSettledPrefix);
    fadeTimeout = fadeOutRuns(runs);
  }

  function destroy() {
    settled = true;
    if (pendingIdle !== null) cancelIdle(pendingIdle);
    if (fadeTimeout !== null) window.clearTimeout(fadeTimeout);
    revealAll();
    restoreRuns(runs);
  }

  function tick(now: number) {
    if (settled) return;
    const elapsed = now - startTime;
    let allSettled = true;
    for (const run of runs) {
      for (let index = run.collapseCursor; index < run.spans.length; index++) {
        if (!run.active[index]) continue;
        const span = run.spans[index];
        if (!span) continue;
        const animatedIndex = run.globalOffset + index - skipCharacters;
        const settleAt = (animatedIndex + characterOffset) * STAGGER_MS;
        if (elapsed >= Math.max(0, settleAt - FADE_LEAD_MS)) {
          span.classList.add("scraps-markdown-decode-visible");
          if (!run.revealed) {
            run.revealed = true;
            run.decoratedAncestors.forEach((ancestor) =>
              ancestor.removeAttribute("data-streaming-hidden"),
            );
          }
        }
        if (elapsed >= settleAt) {
          span.removeAttribute(DECODE_ATTRIBUTE);
          run.active[index] = false;
        } else {
          allSettled = false;
        }
      }
    }
    scheduleCollapse();
    if (allSettled || elapsed >= MAX_DURATION_MS + characterOffset * STAGGER_MS) settle();
    else requestAnimationFrame(tick);
  }

  requestAnimationFrame(tick);
  return { destroy, settle };
}

import type { Token as MarkedToken } from "marked";
import type { ReactNode } from "react";

import {
  DefaultBlockquote,
  DefaultCodeBlock,
  DefaultEmphasis,
  DefaultHeading,
  DefaultHorizontalRule,
  DefaultHtmlBlock,
  DefaultInlineCode,
  DefaultLineBreak,
  DefaultLink,
  DefaultListItem,
  DefaultOrderedList,
  DefaultParagraph,
  DefaultStrikethrough,
  DefaultStrong,
  DefaultTable,
  DefaultTableBody,
  DefaultTableCell,
  DefaultTableHead,
  DefaultTableHeaderCell,
  DefaultTableRow,
  DefaultTag,
  DefaultTaskList,
  DefaultTaskListItem,
  DefaultText,
  DefaultUnorderedList,
  Checkbox,
} from "./markdown-default-components";
import {
  isInternalHref,
  isSafeHref,
  isTagToken,
  sanitizeHtml,
  type MarkdownToken,
} from "./markdown-parser";
import type { MarkdownComponents } from "./markdown-types";

const TAG_START_RE = /\{%\s+[\w-]/;

function isHeadingLevel(value: number): value is 1 | 2 | 3 | 4 | 5 | 6 {
  return Number.isInteger(value) && value >= 1 && value <= 6;
}

function stripPartialTag(text: string): string {
  const index = text.lastIndexOf("{%");
  if (index === -1 || !TAG_START_RE.test(text.slice(index))) return text;
  return text.slice(0, index);
}

function hasInlineHtml(tokens: MarkedToken[]): boolean {
  return tokens.some((token) => token.type === "html");
}

function renderInline(
  tokens: MarkedToken[] | undefined,
  components: MarkdownComponents,
  taskLabel?: string,
): ReactNode {
  if (!tokens) return null;
  if (hasInlineHtml(tokens)) {
    const raw = tokens.map((token) => token.raw).join("");
    return <span dangerouslySetInnerHTML={{ __html: sanitizeHtml(raw) }} />;
  }
  return tokens.map((token, index) => (
    <MarkdownTokenView
      key={index}
      token={token as MarkdownToken}
      components={components}
      taskLabel={taskLabel}
    />
  ));
}

export function MarkdownTokenView({
  components,
  token,
  taskLabel,
}: {
  components: MarkdownComponents;
  token: MarkdownToken;
  taskLabel?: string;
}): ReactNode {
  if (isTagToken(token)) {
    const Tag = components.Tag ?? DefaultTag;
    return (
      <Tag
        Default={DefaultTag}
        attrs={token.attrs}
        data={token.data}
        level={token.level}
        name={token.name}
      />
    );
  }

  switch (token.type) {
    case "space":
      return null;
    case "paragraph": {
      const Paragraph = components.Paragraph ?? DefaultParagraph;
      return (
        <Paragraph Default={DefaultParagraph}>{renderInline(token.tokens, components)}</Paragraph>
      );
    }
    case "heading": {
      const Heading = components.Heading ?? DefaultHeading;
      const level = isHeadingLevel(token.depth) ? token.depth : 1;
      return (
        <Heading Default={DefaultHeading} level={level}>
          {renderInline(token.tokens, components)}
        </Heading>
      );
    }
    case "code": {
      const CodeBlock = components.CodeBlock ?? DefaultCodeBlock;
      return (
        <CodeBlock Default={DefaultCodeBlock} lang={token.lang ?? undefined}>
          {token.text}
        </CodeBlock>
      );
    }
    case "codespan": {
      const InlineCode = components.InlineCode ?? DefaultInlineCode;
      return <InlineCode Default={DefaultInlineCode}>{token.text}</InlineCode>;
    }
    case "blockquote": {
      const Blockquote = components.Blockquote ?? DefaultBlockquote;
      return (
        <Blockquote Default={DefaultBlockquote}>
          {renderInline(token.tokens, components)}
        </Blockquote>
      );
    }
    case "list": {
      const isTaskList = token.items.some((item) => item.task);
      const List = isTaskList
        ? (components.TaskList ?? DefaultTaskList)
        : token.ordered
          ? (components.OrderedList ?? DefaultOrderedList)
          : (components.UnorderedList ?? DefaultUnorderedList);
      const Default = isTaskList
        ? DefaultTaskList
        : token.ordered
          ? DefaultOrderedList
          : DefaultUnorderedList;
      return (
        <List Default={Default}>
          {token.items.map((item, index) => (
            <MarkdownTokenView key={index} token={item} components={components} />
          ))}
        </List>
      );
    }
    case "list_item": {
      if (token.task) {
        const TaskListItem = components.TaskListItem ?? DefaultTaskListItem;
        return (
          <TaskListItem Default={DefaultTaskListItem} checked={token.checked ?? false}>
            {renderInline(token.tokens, components, token.text)}
          </TaskListItem>
        );
      }
      const ListItem = components.ListItem ?? DefaultListItem;
      return (
        <ListItem Default={DefaultListItem}>{renderInline(token.tokens, components)}</ListItem>
      );
    }
    case "checkbox":
      return <Checkbox aria-label={taskLabel} checked={token.checked} readOnly />;
    case "table": {
      const Table = components.Table ?? DefaultTable;
      const TableHead = components.TableHead ?? DefaultTableHead;
      const TableBody = components.TableBody ?? DefaultTableBody;
      const TableRow = components.TableRow ?? DefaultTableRow;
      const TableHeaderCell = components.TableHeaderCell ?? DefaultTableHeaderCell;
      const TableCell = components.TableCell ?? DefaultTableCell;
      return (
        <Table Default={DefaultTable}>
          <TableHead Default={DefaultTableHead}>
            <TableRow Default={DefaultTableRow}>
              {token.header.map((cell, index) => (
                <TableHeaderCell
                  key={index}
                  Default={DefaultTableHeaderCell}
                  align={token.align[index] ?? undefined}
                >
                  {renderInline(cell.tokens, components)}
                </TableHeaderCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody Default={DefaultTableBody}>
            {token.rows.map((row, rowIndex) => (
              <TableRow key={rowIndex} Default={DefaultTableRow}>
                {row.map((cell, cellIndex) => (
                  <TableCell
                    key={cellIndex}
                    Default={DefaultTableCell}
                    align={token.align[cellIndex] ?? undefined}
                  >
                    {renderInline(cell.tokens, components)}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      );
    }
    case "hr": {
      const HorizontalRule = components.HorizontalRule ?? DefaultHorizontalRule;
      return <HorizontalRule Default={DefaultHorizontalRule} />;
    }
    case "html": {
      const Html = components.Html ?? DefaultHtmlBlock;
      return <Html Default={DefaultHtmlBlock} html={sanitizeHtml(token.text)} />;
    }
    case "strong": {
      const Strong = components.Strong ?? DefaultStrong;
      return <Strong Default={DefaultStrong}>{renderInline(token.tokens, components)}</Strong>;
    }
    case "em": {
      const Emphasis = components.Emphasis ?? DefaultEmphasis;
      return (
        <Emphasis Default={DefaultEmphasis}>{renderInline(token.tokens, components)}</Emphasis>
      );
    }
    case "del": {
      const Strikethrough = components.Strikethrough ?? DefaultStrikethrough;
      return (
        <Strikethrough Default={DefaultStrikethrough}>
          {renderInline(token.tokens, components)}
        </Strikethrough>
      );
    }
    case "link": {
      if (!isSafeHref(token.href) && !isInternalHref(token.href)) {
        return <span>{renderInline(token.tokens, components)}</span>;
      }
      const Link = components.Link ?? DefaultLink;
      return (
        <Link Default={DefaultLink} href={token.href} title={token.title}>
          {renderInline(token.tokens, components)}
        </Link>
      );
    }
    case "image": {
      const Image = components.Image;
      // An explicit renderer is required so Markdown cannot start network requests.
      return Image ? <Image src={token.href} alt={token.text} title={token.title} /> : null;
    }
    case "text": {
      if (token.tokens) return renderInline(token.tokens, components);
      const text = stripPartialTag(token.text);
      const Text = components.Text;
      return Text ? <Text Default={DefaultText}>{text}</Text> : text;
    }
    case "escape":
      return token.text;
    case "br": {
      const LineBreak = components.LineBreak ?? DefaultLineBreak;
      return <LineBreak Default={DefaultLineBreak} />;
    }
    case "def":
      return null;
    default:
      return null;
  }
}

import type { ComponentType, ReactNode } from "react";

type WithDefault<Props> = Props & { Default: ComponentType<Props> };

export type MarkdownComponents = Partial<{
  Blockquote: ComponentType<WithDefault<{ children: ReactNode }>>;
  CodeBlock: ComponentType<WithDefault<{ children: string; lang?: string }>>;
  Emphasis: ComponentType<WithDefault<{ children: ReactNode }>>;
  Heading: ComponentType<WithDefault<{ children: ReactNode; level: 1 | 2 | 3 | 4 | 5 | 6 }>>;
  HorizontalRule: ComponentType<WithDefault<Record<PropertyKey, unknown>>>;
  Html: ComponentType<WithDefault<{ html: string }>>;
  Image: ComponentType<{ src: string; alt?: string; title?: string | null }>;
  InlineCode: ComponentType<WithDefault<{ children: string }>>;
  LineBreak: ComponentType<WithDefault<Record<PropertyKey, unknown>>>;
  Link: ComponentType<WithDefault<{ children: ReactNode; href: string; title?: string | null }>>;
  ListItem: ComponentType<WithDefault<{ children: ReactNode; checked?: boolean }>>;
  OrderedList: ComponentType<WithDefault<{ children: ReactNode }>>;
  Paragraph: ComponentType<WithDefault<{ children: ReactNode }>>;
  Strikethrough: ComponentType<WithDefault<{ children: ReactNode }>>;
  Strong: ComponentType<WithDefault<{ children: ReactNode }>>;
  Table: ComponentType<WithDefault<{ children: ReactNode }>>;
  TableBody: ComponentType<WithDefault<{ children: ReactNode }>>;
  TableCell: ComponentType<
    WithDefault<{ children: ReactNode; align?: "left" | "right" | "center" }>
  >;
  TableHead: ComponentType<WithDefault<{ children: ReactNode }>>;
  TableHeaderCell: ComponentType<
    WithDefault<{ children: ReactNode; align?: "left" | "right" | "center" }>
  >;
  TableRow: ComponentType<WithDefault<{ children: ReactNode }>>;
  Tag: ComponentType<
    WithDefault<{
      attrs: Record<string, string>;
      data: unknown;
      level: "block" | "inline";
      name: string;
    }>
  >;
  TaskList: ComponentType<WithDefault<{ children: ReactNode }>>;
  TaskListItem: ComponentType<WithDefault<{ checked: boolean; children: ReactNode }>>;
  Text: ComponentType<WithDefault<{ children: string }>>;
  UnorderedList: ComponentType<WithDefault<{ children: ReactNode }>>;
}>;

"use client";

import { useLayoutEffect, useMemo, useRef } from "react";

import { Stack } from "./layout";
import { lexMarkdown } from "./markdown-parser";
import {
  countMarkdownGraphemes,
  streamingAnimationStyles,
  useStreamingAnimation,
  useTextDecodeAnimation,
} from "./markdown-streaming";
import { MarkdownTokenView } from "./markdown-token";
import type { MarkdownComponents } from "./markdown-types";

export interface MarkdownProps {
  raw: string;
  components?: MarkdownComponents;
  variant?: "static" | "streaming";
}

export function Markdown({ raw, components = {}, variant = "static" }: MarkdownProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const previousTextLengths = useRef(new Map<number, number>());
  const isStreaming = variant === "streaming";
  const tokens = useMemo(() => lexMarkdown(raw), [raw]);
  const elements = useMemo(
    () =>
      tokens.map((token, index) => (
        <MarkdownTokenView
          key={isStreaming ? `${index}:${token.raw.length}` : index}
          token={token}
          components={components}
        />
      )),
    [components, isStreaming, tokens],
  );

  useStreamingAnimation(containerRef, isStreaming);

  useLayoutEffect(() => {
    if (!isStreaming || !containerRef.current) return;
    const nextTextLengths = new Map<number, number>();
    let changed = false;
    Array.from(containerRef.current.children).forEach((child, index) => {
      if (!(child instanceof HTMLElement)) return;
      const length = countMarkdownGraphemes(child.textContent ?? "");
      const previousLength = previousTextLengths.current.get(index) ?? 0;
      if (previousLength > 0) child.dataset.skip = String(previousLength);
      if (length !== previousLength) changed = true;
      nextTextLengths.set(index, length);
    });
    if (changed) previousTextLengths.current = nextTextLengths;
  }, [elements, isStreaming]);

  return (
    <Stack
      ref={containerRef}
      data-streaming={isStreaming || undefined}
      flex={1}
      gap="lg"
      className="break-words"
    >
      {elements}
    </Stack>
  );
}

export { useTextDecodeAnimation };
export { streamingAnimationStyles };
